using System.Net;
using System.Net.Http.Json;
using System.Text;
using System.Text.Json;
using Microsoft.IdentityModel.Tokens;

namespace Acme.Ticketing.Tests;

[TestClass]
public class TicketingScenarioTests : ApiTestBase
{
    private async Task<JsonElement> CreateVenueAsync(string name = "Arena", int capacity = 100)
    {
        var r = await Client.PostAsJsonAsync("/venues", new
        {
            name,
            capacity,
            address = new { street = "1 Main St", city = "Paris", postalCode = "75001" },
        });
        Assert.AreEqual(HttpStatusCode.Created, r.StatusCode, await r.Content.ReadAsStringAsync());
        return await r.Content.ReadFromJsonAsync<JsonElement>();
    }

    private async Task<JsonElement> CreateShowAsync(Guid venueId, int status = 1, DateTime? startsAt = null, int quota = 5)
    {
        var r = await Client.PostAsJsonAsync("/shows", new
        {
            title = "Concert",
            startsAt = startsAt ?? DateTime.UtcNow.AddDays(10),
            status,
            venueId,
            ticketTiers = new[] { new { name = "Gold", price = 12.5m, quota, sold = 99 } },
        });
        Assert.AreEqual(HttpStatusCode.Created, r.StatusCode, await r.Content.ReadAsStringAsync());
        return await r.Content.ReadFromJsonAsync<JsonElement>();
    }

    private Task<HttpResponseMessage> BookAsync(Guid showId, string tier = "Gold", string email = "a@b.c", int quantity = 1) =>
        Client.PostAsJsonAsync("/box-office/book", new { showId, tier, customerEmail = email, quantity });

    [TestMethod]
    public async Task VenueRoundTripWithShowsAndUniqueName()
    {
        var venue = await CreateVenueAsync();
        var id = venue.GetProperty("id").GetGuid();
        Assert.AreEqual("Paris", venue.GetProperty("address").GetProperty("city").GetString());

        await CreateShowAsync(id);
        var detail = await Client.GetFromJsonAsync<JsonElement>($"/venues/{id}");
        Assert.AreEqual(1, detail.GetProperty("shows").GetArrayLength());

        var dup = await Client.PostAsJsonAsync("/venues", new
        {
            name = "Arena", capacity = 1, address = new { street = "s", city = "c", postalCode = "p" },
        });
        Assert.AreEqual(HttpStatusCode.Conflict, dup.StatusCode);

        var update = await Client.PutAsJsonAsync($"/venues/{id}", new
        {
            name = "Arena 2", capacity = 200, address = new { street = "s", city = "c", postalCode = "p" },
        });
        Assert.AreEqual(HttpStatusCode.OK, update.StatusCode);

        Assert.AreEqual(HttpStatusCode.Conflict, (await Client.DeleteAsync($"/venues/{id}")).StatusCode);
    }

    [TestMethod]
    public async Task VenueValidation()
    {
        var r = await Client.PostAsJsonAsync("/venues", new
        {
            name = "", capacity = 1, address = new { street = new string('x', 101), city = "c", postalCode = "p" },
        });
        await AssertInvalidAsync(r, "Name");
        await AssertInvalidAsync(r, "Address.Street");
    }

    [TestMethod]
    public async Task ShowTiersSyncAndCapacity()
    {
        var venueId = (await CreateVenueAsync(capacity: 10)).GetProperty("id").GetGuid();
        var show = await CreateShowAsync(venueId, status: 0, quota: 4);
        var showId = show.GetProperty("id").GetGuid();
        var tier = show.GetProperty("ticketTiers")[0];
        Assert.AreEqual(0, tier.GetProperty("sold").GetInt32());

        object Body(object[] tiers) => new { title = "Concert", startsAt = DateTime.UtcNow.AddDays(1), status = 0, venueId, ticketTiers = tiers };

        var tooMany = await Client.PutAsJsonAsync($"/shows/{showId}", Body([
            new { id = tier.GetProperty("id").GetGuid(), name = "Gold", price = 1m, quota = 4 },
            new { name = "Silver", price = 1m, quota = 7 },
        ]));
        await AssertInvalidAsync(tooMany, "TicketTiers");

        var ok = await Client.PutAsJsonAsync($"/shows/{showId}", Body([
            new { id = tier.GetProperty("id").GetGuid(), name = "Gold+", price = 2m, quota = 4 },
            new { name = "Silver", price = 1m, quota = 6 },
        ]));
        Assert.AreEqual(HttpStatusCode.OK, ok.StatusCode, await ok.Content.ReadAsStringAsync());
        var updated = await ok.Content.ReadFromJsonAsync<JsonElement>();
        Assert.AreEqual(2, updated.GetProperty("ticketTiers").GetArrayLength());

        var removed = await Client.PutAsJsonAsync($"/shows/{showId}", Body([]));
        Assert.AreEqual(0, (await removed.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("ticketTiers").GetArrayLength());

        var unknownVenue = await Client.PostAsJsonAsync("/shows", new { title = "t", startsAt = DateTime.UtcNow, status = 0, venueId = Guid.NewGuid(), ticketTiers = Array.Empty<object>() });
        await AssertInvalidAsync(unknownVenue, "VenueId");

        var badStatus = await Client.PostAsJsonAsync("/shows", new { title = "t", startsAt = DateTime.UtcNow, status = 9, venueId, ticketTiers = Array.Empty<object>() });
        Assert.AreEqual(HttpStatusCode.BadRequest, badStatus.StatusCode);

        Assert.AreEqual(HttpStatusCode.NoContent, (await Client.DeleteAsync($"/shows/{showId}")).StatusCode);
    }

    [TestMethod]
    public async Task BookingFlow()
    {
        var venueId = (await CreateVenueAsync()).GetProperty("id").GetGuid();
        var showId = (await CreateShowAsync(venueId, quota: 3)).GetProperty("id").GetGuid();

        Assert.AreEqual(HttpStatusCode.BadRequest, (await BookAsync(showId, quantity: 0)).StatusCode);
        Assert.AreEqual(HttpStatusCode.BadRequest, (await BookAsync(showId, quantity: 11)).StatusCode);
        Assert.AreEqual(HttpStatusCode.BadRequest, (await BookAsync(showId, email: "nope")).StatusCode);
        Assert.AreEqual(HttpStatusCode.NotFound, (await BookAsync(Guid.NewGuid())).StatusCode);
