        var request = new HttpRequestMessage(HttpMethod.Get, uri);
        if (token is not null) request.Headers.Authorization = new("Bearer", token);
        return (await Client.SendAsync(request)).StatusCode;
    }

    [TestMethod]
    public async Task TokenIsValidated()
    {
        Assert.AreEqual(HttpStatusCode.Unauthorized, await GetAsync("/venues", null));
        Assert.AreEqual(HttpStatusCode.Unauthorized, await GetAsync("/venues", Token("other", DateTime.UtcNow.AddHours(1))));
        Assert.AreEqual(HttpStatusCode.Unauthorized, await GetAsync("/venues", Token(Key, DateTime.UtcNow.AddMinutes(-1))));
        Assert.AreEqual(HttpStatusCode.OK, await GetAsync("/venues", Token(Key, DateTime.UtcNow.AddHours(1))));
        Assert.AreEqual(HttpStatusCode.Forbidden, await GetAsync("/bookings", Token(Key, DateTime.UtcNow.AddHours(1))));
        Assert.AreEqual(HttpStatusCode.OK, await GetAsync("/bookings", Token(Key, DateTime.UtcNow.AddHours(1), "ManageShows")));
        Assert.AreEqual(HttpStatusCode.OK, await GetAsync("/bookings", Token(Key, DateTime.UtcNow.AddHours(1), "*")));
    }
}
